import heapq
from collections import defaultdict


def shortest_path(edges, start, end):
    # Check for negative weights
    for edge in edges:
        if edge[2] < 0:
            raise ValueError("Edge weights cannot be negative.")

    # Handle the case where start and end are the same node
    if start == end:
        return (0, [start])

    # Build the adjacency list
    graph = defaultdict(list)
    nodes = {start, end}
    for u, v, w in edges:
        graph[u].append((v, w))
        nodes.add(u)
        nodes.add(v)

    # If start or end are not in the graph at all, no path exists
    if start not in nodes or end not in nodes:
        return (None, None)

    # Priority queue stores tuples of (current_distance, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Dictionary to store the shortest distance found to each node
    shortest_distances = {start: 0}

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # If we reached the destination, return the result
        if current_node == end:
            return (current_distance, path)

        # If a shorter distance to this node has already been found, skip
        if current_distance > shortest_distances.get(
            current_node, float("inf")
        ):
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If we found a shorter path to the neighbor
            if distance < shortest_distances.get(neighbor, float("inf")):
                shortest_distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor, path + [neighbor]))

    # If the priority queue is exhausted and we haven't reached 'end'
    return (None, None)
